// IAM Data Collector — v2
// Triggered by app: ex.params = { accountId, vaultId, userEmail? }
// Manual run:       ex.input  = { accountId, dtApiBase, oauth: { credentialId, scope, tokenUrl } }
//
// Snapshot rotation: 10 slots (snapshot_0 = newest, snapshot_9 = oldest)
// User mode:  when userEmail is provided → collect only that user's groups,
//             bound policies and boundaries (faster & lighter)
// Full mode:  no userEmail → collect all IAM data

import { credentialVaultClient }  from '@dynatrace-sdk/client-classic-environment-v2';
import { execution }              from '@dynatrace-sdk/automation-utils';
import { queryExecutionClient }   from '@dynatrace-sdk/client-query';

const OAUTH_TOKEN_URL = 'https://sso.dynatrace.com/sso/oauth2/token';
const BASE_URL        = 'https://api.dynatrace.com';
const NUM_SNAPSHOTS   = 10;

export default async function () {
  const ex = await execution();

  // Runtime params (app trigger) take priority over Default Input (manual run)
  const params = ex.params ?? {};
  const cfg    = ex.input  ?? {};

  const accountId    = String(params.accountId ?? cfg.accountId ?? '').trim();
  const credentialId = String(params.vaultId   ?? cfg.oauth?.credentialId ?? '').trim();
  const scope        = String(cfg.oauth?.scope    ?? 'iam-policies-management account-idm-read').trim();
  const tokenUrl     = String(cfg.oauth?.tokenUrl ?? OAUTH_TOKEN_URL).trim();
  const dtApiBase    = String(cfg.dtApiBase       ?? BASE_URL).trim();
  const userEmail    = String(params.userEmail    ?? '').trim().toLowerCase();
  const isUserMode   = !!userEmail;

  if (!accountId)    throw new Error('Missing accountId (params or input.accountId)');
  if (!credentialId) throw new Error('Missing vaultId / credentialId (params.vaultId or input.oauth.credentialId)');

  console.log('accountId   :', accountId);
  console.log('userEmail   :', userEmail || '(none — full mode)');

  // ── Read clientId / clientSecret from Vault ───────────────────────────────
  const details      = await credentialVaultClient.getCredentialsDetails({ id: credentialId });
  const clientId     = details.username;
  const clientSecret = details.password ?? details.token;
  if (!clientId || !clientSecret) {
    throw new Error(`Vault ${credentialId}: username=${clientId}, password=${!!clientSecret}`);
  }
  console.log('clientId    :', clientId);

  // ── OAuth token ───────────────────────────────────────────────────────────
  const tokenResp = await fetch(tokenUrl, {
    method:  'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' },
    body: new URLSearchParams({
      grant_type:    'client_credentials',
      client_id:     clientId,
      client_secret: clientSecret,
      scope,
      resource: `urn:dtaccount:${accountId}`,
    }).toString(),
  });
  const tokenJson = await tokenResp.json();
  if (!tokenResp.ok) throw new Error(`OAuth ${tokenResp.status}: ${JSON.stringify(tokenJson)}`);
  const token = String(tokenJson.access_token ?? '').trim();
  if (!token) throw new Error('OAuth: missing access_token');
  console.log('OAuth OK');

  // ── IAM API helper ────────────────────────────────────────────────────────
  async function dtGet(url) {
    console.log('GET', url);
    const r    = await fetch(url, {
      headers: { authorization: `Bearer ${token}`, accept: 'application/json' },
    });
    console.log('   →', r.status, r.headers.get('content-type'));
    const text = await r.text();
    if (!r.ok) throw new Error(`IAM API ${r.status}: ${url} — ${text.slice(0, 300)}`);
    try { return JSON.parse(text); }
    catch (e) { throw new Error(`JSON parse failed for ${url}: ${text.slice(0, 200)}`); }
  }

  // ── Normalizers ───────────────────────────────────────────────────────────
  function normalizeGroup(raw) {
    return {
      id:             String(raw.uuid || raw.id           || ''),
      name:           String(raw.name || raw.displayName  || ''),
      description:    String(raw.description ?? ''),
      // memberCount is returned by the groups list endpoint; fall back to 0 if absent
      userCount:      Number(raw.memberCount ?? raw.usersCount ?? raw.numUsers ?? raw.members?.length ?? 0),
      federationType: String(raw.federationType ?? raw.type ?? ''),
      // accessRight: classic role-based env access — enriched by fetchGroupDetails
      accessRight:    {},
      bindings:       [],
    };
  }

  function normalizePolicy(raw, defaults = {}) {
    return {
      id:             String(raw.uuid        || raw.id          || ''),
      name:           String(raw.name        || raw.displayName || ''),
      description:    String(raw.description ?? ''),
      category:       String(raw.category    ?? ''),
      levelType:      String(raw.levelType   || defaults.levelType || 'account'),
      levelId:        String(raw.levelId     || defaults.levelId   || ''),
      statementQuery: typeof raw.statementQuery === 'string' ? raw.statementQuery : undefined,
    };
  }

  // Fetch group description and classic role-based accessRight
  async function fetchGroupDetails(groupId) {
    try {
      const data = await dtGet(`${dtApiBase}/iam/v1/accounts/${accountId}/groups/${groupId}`);
      const description = String(data.description ?? '');
      const accessRight = (data.accessRight && typeof data.accessRight === 'object' && !Array.isArray(data.accessRight))
        ? data.accessRight : {};
      return { description, accessRight };
    } catch (e) {
      console.warn(`Group details ${groupId}: ${e.message}`);
      return { description: '', accessRight: {} };
    }
  }

  // Fetch the actual number of users in a group via the dedicated endpoint
  async function fetchGroupUserCount(groupId) {
    try {
      const data = await dtGet(`${dtApiBase}/iam/v1/accounts/${accountId}/groups/${groupId}/users`);
      return Number(data.totalCount ?? data.count ?? (Array.isArray(data.items) ? data.items.length : 0));
    } catch (e) {
      console.warn(`userCount for group ${groupId}: ${e.message}`);
      return 0;
    }
  }

  function normalizeBoundary(raw) {
    return {
      id:    String(raw.uuid || raw.id          || ''),
      name:  String(raw.name || raw.displayName || ''),
      query: String(raw.boundaryQuery           || ''),
    };
  }

  function buildGroupBindingMap(leveledContainers) {
    const map = new Map();
    for (const container of leveledContainers) {
      const { levelType = '', levelId = '', levelName = '' } = container;
      for (const pb of (container.policyBindings ?? [])) {
        const policyId = String(pb.policyUuid || pb.policyId || pb.uuid || '');
        if (!policyId) continue;
        const boundaryIds = (pb.boundaries ?? [])
          .map(b => (typeof b === 'string' ? b : String(b.uuid || b.id || '')))
          .filter(Boolean);
        const rawParams = pb.parameters || pb.bindParams || pb.bindParameters;
        const bindParams = (rawParams && typeof rawParams === 'object' && !Array.isArray(rawParams))
          ? Object.fromEntries(Object.entries(rawParams).map(([k, v]) => [k, String(v)]))
          : {};
        for (const groupIdRaw of (pb.groups ?? [])) {
          const groupId = typeof groupIdRaw === 'string'
            ? groupIdRaw
            : String(groupIdRaw.uuid || groupIdRaw.id || '');
          if (!groupId) continue;
          if (!map.has(groupId)) map.set(groupId, []);
          map.get(groupId).push({ policyId, boundaryIds, bindParams, levelType, levelId, levelName });
        }
      }
    }
    return map;
  }

  // ── Fetch environments ────────────────────────────────────────────────────
  async function fetchEnvironments() {
    try {
      const data = await dtGet(`${dtApiBase}/env/v1/accounts/${accountId}/environments`);
      return (data.tenantResources ?? [])
        .map(t => ({ id: String(t.id || ''), name: String(t.name || t.id || '') }))
        .filter(t => t.id);
    } catch (e) { console.error('fetchEnvironments:', e.message); return []; }
  }

  // ── Fetch all bindings (account + all environments) ───────────────────────
  async function fetchAllBindings() {
    const [accountBindingsData, environments] = await Promise.all([
      dtGet(`${dtApiBase}/iam/v1/repo/account/${accountId}/bindings`),
      fetchEnvironments(),
    ]);
    const envResults = await Promise.all(
      environments.map(env =>
        dtGet(`${dtApiBase}/iam/v1/repo/environment/${env.id}/bindings`)
          .then(data => ({ env, data }))
          .catch(e => { console.error(`env bindings ${env.id}:`, e.message); return null; })
      )
    );
    const leveledContainers = [
      {
        levelType:      'account',
        levelId:        accountId,
        levelName:      'Account',
        policyBindings: Array.isArray(accountBindingsData.policyBindings)
          ? accountBindingsData.policyBindings
          : Array.isArray(accountBindingsData.bindings) ? accountBindingsData.bindings : [],
      },
      ...envResults
        .filter(Boolean)
        .map(({ env, data }) => ({
          levelType:      'environment',
          levelId:        env.id,
          levelName:      env.name,
          policyBindings: Array.isArray(data.policyBindings)
            ? data.policyBindings
            : Array.isArray(data.bindings) ? data.bindings : [],
        })),
    ];
    return { leveledContainers, environments };
  }

  // ── Extract statementQuery from policy detail response ────────────────────
  function extractStatementQuery(detail) {
    if (typeof detail.statementQuery === 'string' && detail.statementQuery) return detail.statementQuery;
    if (Array.isArray(detail.statements) && detail.statements.length) {
      return detail.statements.map(s => {
        const effect  = String(s.effect  || 'ALLOW');
        const actions = (s.actions || []).join(', ');
        const conds   = (s.conditions || [])
          .map(c => `${c.name || ''} = "${c.value || ''}"`)
          .join(' AND ');
        return conds ? `${effect} ${actions}\n  WHERE ${conds}` : `${effect} ${actions}`;
      }).join('\n');
    }
    return undefined;
  }

  // ── Fetch paginated boundaries ────────────────────────────────────────────
  async function fetchAllBoundaries() {
    const all = [];
    let page  = 1;
    while (true) {
      const url  = `${dtApiBase}/iam/v1/repo/account/${accountId}/boundaries?size=500&page=${page}`;
      const data = await dtGet(url);
      const items = Array.isArray(data.content)    ? data.content
                  : Array.isArray(data.items)       ? data.items
                  : Array.isArray(data.boundaries)  ? data.boundaries
                  : Array.isArray(data)              ? data : [];
      all.push(...items);
      const total = Number(data.totalCount || data.count || 0);
      if (all.length >= total || items.length < 500) break;
      page++;
    }
    return all.map(normalizeBoundary);
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // ── Data collection ───────────────────────────────────────────────────────
  // ═══════════════════════════════════════════════════════════════════════════

  let groups, policies, boundaries, environments;
  const BATCH = 8;

  if (isUserMode) {
    // ── USER MODE: collect only data relevant to the specified user ──────────
    // This is faster and stores a much smaller dataset:
    //   - Only the groups the user belongs to
    //   - Only the policies those groups are bound to
    //   - Only the boundaries referenced by those policy bindings
    console.log(`User mode: collecting data for ${userEmail}`);

    // Step 1: get user's group memberships
    const userData = await dtGet(
      `${dtApiBase}/iam/v1/accounts/${accountId}/users/${encodeURIComponent(userEmail)}`
    );
    const rawGrps = Array.isArray(userData.groups)
      ? userData.groups
      : Array.isArray(userData.userGroups) ? userData.userGroups : [];
    const userGroupIdSet = new Set(
      rawGrps
        .map(g => typeof g === 'string' ? g : String(g.uuid || g.id || ''))
        .filter(Boolean)
    );
    console.log(`User belongs to ${userGroupIdSet.size} groups`);

    // Step 2: fetch all groups (for names) and all bindings (to know policies per group)
    const [groupsData, { leveledContainers, environments: envs }] = await Promise.all([
      dtGet(`${dtApiBase}/iam/v1/accounts/${accountId}/groups`),
      fetchAllBindings(),
    ]);
    environments = envs;

    const rawGroups      = Array.isArray(groupsData.items) ? groupsData.items
                         : Array.isArray(groupsData)        ? groupsData : [];
    const groupBindingMap = buildGroupBindingMap(leveledContainers);

    // Step 3: filter to only user's groups and attach their bindings
    groups = rawGroups
      .map(normalizeGroup)
      .filter(g => userGroupIdSet.has(g.id))
      .map(g => { g.bindings = groupBindingMap.get(g.id) ?? []; return g; });
    console.log(`Filtered to ${groups.length} user groups`);

    // Step 4: collect policy IDs and boundary IDs needed by user's groups
    const userPolicyIdSet   = new Set();
    const userBoundaryIdSet = new Set();
    for (const g of groups) {
      for (const b of g.bindings) {
        if (b.policyId) userPolicyIdSet.add(b.policyId);
        for (const bid of b.boundaryIds) if (bid) userBoundaryIdSet.add(bid);
      }
    }
    console.log(`User needs ${userPolicyIdSet.size} policies, ${userBoundaryIdSet.size} boundaries`);

    // Step 5: fetch only the policies the user has access to (with full details incl. statementQuery)
    policies = [];
    const policyIds = [...userPolicyIdSet];
    for (let i = 0; i < policyIds.length; i += BATCH) {
      await Promise.all(policyIds.slice(i, i + BATCH).map(async (policyId) => {
        try {
          let detail, defaults;
          try {
            detail   = await dtGet(`${dtApiBase}/iam/v1/repo/account/${accountId}/policies/${policyId}`);
            defaults = { levelType: 'account', levelId: accountId };
          } catch {
            detail   = await dtGet(`${dtApiBase}/iam/v1/repo/global/global/policies/${policyId}`);
            defaults = { levelType: 'global', levelId: 'global' };
          }
          const p  = normalizePolicy(detail, defaults);
          const sq = extractStatementQuery(detail);
          if (sq) p.statementQuery = sq;
          policies.push(p);
        } catch (e) {
          console.warn(`Policy ${policyId}: ${e.message}`);
        }
      }));
    }
    console.log(`Fetched ${policies.length} policies for user`);

    // Step 6: fetch only the boundaries the user has access to
    boundaries = [];
    const boundaryIds = [...userBoundaryIdSet];
    for (let i = 0; i < boundaryIds.length; i += BATCH) {
      await Promise.all(boundaryIds.slice(i, i + BATCH).map(async (boundaryId) => {
        try {
          const detail = await dtGet(
            `${dtApiBase}/iam/v1/repo/account/${accountId}/boundaries/${boundaryId}`
          );
          boundaries.push(normalizeBoundary(detail));
        } catch (e) {
          console.warn(`Boundary ${boundaryId}: ${e.message}`);
        }
      }));
    }
    console.log(`Fetched ${boundaries.length} boundaries for user`);

  } else {
    // ── FULL MODE: collect all IAM data ──────────────────────────────────────
    console.log('Full mode: collecting all IAM data...');

    const groupsData         = await dtGet(`${dtApiBase}/iam/v1/accounts/${accountId}/groups`);
    const policiesData       = await dtGet(`${dtApiBase}/iam/v1/repo/account/${accountId}/policies`);
    const globalPoliciesData = await dtGet(`${dtApiBase}/iam/v1/repo/global/global/policies`)
      .catch(e => { console.error('global policies:', e.message); return null; });

    const { leveledContainers, environments: envs } = await fetchAllBindings();
    environments = envs;
    boundaries   = await fetchAllBoundaries();

    const groupBindingMap = buildGroupBindingMap(leveledContainers);

    function extractRaw(d) {
      return Array.isArray(d?.policies) ? d.policies
           : Array.isArray(d?.items)    ? d.items
           : Array.isArray(d)           ? d : [];
    }

    const rawGroups = Array.isArray(groupsData.items) ? groupsData.items
                    : Array.isArray(groupsData)        ? groupsData : [];

    groups = rawGroups.map(raw => {
      const g    = normalizeGroup(raw);
      g.bindings = groupBindingMap.get(g.id) ?? [];
      return g;
    });

    policies = [
      ...extractRaw(policiesData).map(p      => normalizePolicy(p, { levelType: 'account', levelId: accountId })),
      ...extractRaw(globalPoliciesData).map(p => normalizePolicy(p, { levelType: 'global',  levelId: 'global'  })),
    ];

    console.log(`✓ groups=${groups.length} policies=${policies.length} boundaries=${boundaries.length} envs=${environments.length}`);

    // Enrich policies with statementQuery (individual fetches — list endpoint omits it)
    console.log(`Fetching statement details for ${policies.length} policies...`);
    for (let i = 0; i < policies.length; i += BATCH) {
      await Promise.all(policies.slice(i, i + BATCH).map(async (p) => {
        try {
          const repo = p.levelType === 'global'
            ? `${dtApiBase}/iam/v1/repo/global/global/policies/${p.id}`
            : `${dtApiBase}/iam/v1/repo/account/${accountId}/policies/${p.id}`;
          const detail = await dtGet(repo);
          const sq = extractStatementQuery(detail);
          if (sq) p.statementQuery = sq;
        } catch (e) {
          console.warn(`Policy ${p.id} detail skipped: ${e.message}`);
        }
      }));
    }
    console.log('Policy statements fetched.');
  }

  // ── Enrich groups: user counts + description + classic role-based access ────────────────────────
  console.log(`Fetching user counts and group details for ${groups.length} groups...`);
  for (let i = 0; i < groups.length; i += BATCH) {
    await Promise.all(groups.slice(i, i + BATCH).map(async (g) => {
      const [userCount, details] = await Promise.all([
        fetchGroupUserCount(g.id),
        fetchGroupDetails(g.id),
      ]);
      g.userCount   = userCount;
      g.description = details.description;
      g.accessRight = details.accessRight;
    }));
  }
  console.log('User counts and group details fetched.');

  // ═══════════════════════════════════════════════════════════════════════════
  // ── 10-slot snapshot rotation + upload ───────────────────────────────────
  // snapshot_0 = newest (just collected), snapshot_9 = oldest
  // On each run: snapshot_8→9, snapshot_7→8, ..., snapshot_0→1, new→snapshot_0
  // ═══════════════════════════════════════════════════════════════════════════

  async function uploadLookup(records, filePath) {
    if (!records.length) { console.log(`${filePath}: 0 records – skipped`); return; }
    const content = records.map(r => JSON.stringify(r)).join('\n');
    const form    = new FormData();
    form.append('request', JSON.stringify({
      filePath, parsePattern: 'JSON:json', overwrite: true, lookupField: 'objectId',
    }));
    form.append('content', new Blob([content], { type: 'application/json' }), 'content.json');
    const resp = await fetch('/platform/storage/resource-store/v1/files/tabular/lookup:upload', {
      method: 'POST', body: form,
    });
    if (!resp.ok) {
      const txt = await resp.text();
      throw new Error(`Upload ${filePath} → ${resp.status}: ${txt.slice(0, 300)}`);
    }
    console.log(`Lookup uploaded: ${filePath} (${records.length} records)`);
  }

  async function queryLookup(filePath) {
    try {
      let resp = await queryExecutionClient.queryExecute({
        body: { query: `load "${filePath}"`, fetchTimeoutSeconds: 30, requestTimeoutMilliseconds: 10000 }
      });
      const reqToken = resp.requestToken ?? '';
      const deadline = Date.now() + 30000;
      while (resp.state === 'RUNNING' && Date.now() < deadline && reqToken) {
        await new Promise(r => setTimeout(r, 500));
        resp = await queryExecutionClient.queryPoll({ requestToken: reqToken });
      }
      if (resp.state === 'SUCCEEDED') return resp.result?.records ?? [];
      console.warn(`queryLookup ${filePath}: state=${resp.state}`);
      return [];
    } catch (e) {
      console.warn(`queryLookup ${filePath} skipped: ${e.message}`);
      return [];
    }
  }

  try {
    const TYPES = ['groups', 'policies', 'boundaries', 'meta', 'users'];

    // Rotate: snapshot_(N-2) → snapshot_(N-1), ..., snapshot_0 → snapshot_1
    // Process from highest index down to avoid overwriting data we still need to copy
    for (let i = NUM_SNAPSHOTS - 2; i >= 0; i--) {
      // Parallelise across types for each index level
      await Promise.all(TYPES.map(async (type) => {
        const src     = `/lookups/iam-sankey/snapshot_${i}-${type}`;
        const dst     = `/lookups/iam-sankey/snapshot_${i + 1}-${type}`;
        const records = await queryLookup(src);
        if (records.length > 0) {
          await uploadLookup(records, dst);
          console.log(`Rotated: snapshot_${i}-${type} → snapshot_${i + 1}-${type} (${records.length} records)`);
        }
      }));
    }

    // Build new records for snapshot_0
    const groupRecords = groups.map(g => ({
      objectId:        g.id,
      groupId:         g.id,
      name:            g.name,
      description:     g.description     ?? '',
      userCount:       g.userCount,
      federationType:  g.federationType,
      accessRightJson: JSON.stringify(g.accessRight ?? {}),
      accountId,
      bindingsJson:    JSON.stringify(g.bindings),
    }));
    const policyRecords = policies.map(p => ({
      objectId:       p.id,
      policyId:       p.id,
      name:           p.name,
      description:    p.description  || '',
      category:       p.category     || '',
      levelType:      p.levelType    || '',
      levelId:        p.levelId      || '',
      statementQuery: (p.statementQuery ?? '').slice(0, 4000),
      accountId,
    }));
    const boundaryRecords = boundaries.map(b => ({
      objectId:   b.id,
      boundaryId: b.id,
      name:       b.name,
      query:      b.query,
      accountId,
    }));
    const metaRecords = [{
      objectId:         accountId,
      accountId,
      timestamp:        new Date().toISOString(),
      groupCount:       groups.length,
      policyCount:      policies.length,
      boundaryCount:    boundaries.length,
      envCount:         environments.length,
      userEmail,
      isUserMode,
      environmentsJson: JSON.stringify(environments),
    }];
    // Users table: in user mode, store the user's actual group IDs for UI filtering;
    //              in full mode, store an empty-marker so the slot's table always exists.
    const usersRecords = isUserMode
      ? [{ objectId: userEmail, email: userEmail, groupIds: JSON.stringify(groups.map(g => g.id)), groupCount: groups.length, accountId }]
      : [{ objectId: '__none__', email: '', groupIds: '[]', groupCount: 0, accountId }];

    await uploadLookup(groupRecords,    '/lookups/iam-sankey/snapshot_0-groups');
    await uploadLookup(policyRecords,   '/lookups/iam-sankey/snapshot_0-policies');
    await uploadLookup(boundaryRecords, '/lookups/iam-sankey/snapshot_0-boundaries');
    await uploadLookup(metaRecords,     '/lookups/iam-sankey/snapshot_0-meta');
    await uploadLookup(usersRecords,    '/lookups/iam-sankey/snapshot_0-users');
    console.log('All snapshot_0 lookup tables uploaded — rotation complete.');

  } catch (e) {
    console.error('Lookup upload/rotation failed (non-fatal):', e.message);
  }

  return { groups, policies, boundaries, environments };
}
